Lemma first_fit : forall (k : nat) (l : list (word * word)) (lo n : Z),
  length l = k -> 0 < n -> 0 <= lo -> lo mod 4096 = 0 ->
  exists a, lo <= a /\ a mod 4096 = 0 /\
            a <= lo + live_bytes l + Z.of_nat (length l) * (n + 4095) /\
            forall b s, In (b, s) l -> u b + u s <= a \/ a + n <= u b.
